import{_ as a,o,c as t,a3 as r}from"./chunks/framework.CJlOecQn.js";const p=JSON.parse('{"title":"Phone and internet","description":"The licensed telecom operators in Qatar, how to get a SIM, home fibre, and how to complain to your operator and then to the regulator.","frontmatter":{"title":"Phone and internet","description":"The licensed telecom operators in Qatar, how to get a SIM, home fibre, and how to complain to your operator and then to the regulator.","lastChecked":"2026-10","sourceCount":11},"headers":[],"relativePath":"guide/phone-and-internet.md","filePath":"guide/phone-and-internet.md"}'),n={name:"guide/phone-and-internet.md"};function s(f,e,i,l,c,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="phone-and-internet" tabindex="-1">Phone and internet <a class="header-anchor" href="#phone-and-internet" aria-label="Permalink to &quot;Phone and internet&quot;">​</a></h1><p>Two companies sell mobile and fixed services in Qatar: Ooredoo and Vodafone. The Communications Regulatory Authority (CRA) lists both as licensees for mobile and for fixed services, plus Qatar National Broadband Network (QNBN) as a passive fixed licensee.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p><h2 id="getting-a-sim" tabindex="-1">Getting a SIM <a class="header-anchor" href="#getting-a-sim" aria-label="Permalink to &quot;Getting a SIM&quot;">​</a></h2><p><strong>What you need.</strong> Ooredoo&#39;s terms ask for your original, valid QID, GCC ID or passport when you buy a service. If you buy for someone else, it needs the original documents of both of you.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup> Vodafone asks for a passport or valid Qatari ID for prepaid, and a Qatar ID for postpaid.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></p><p><strong>Where to buy.</strong> Vodafone sells an Instant SIM at more than 2,600 locations and you activate it yourself: insert it, scan the QR code, choose a plan, scan your QID or passport, then sign the terms.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></p><p><strong>Prepaid or postpaid.</strong> Prepaid means you recharge when you want. Ooredoo&#39;s prepaid service is called Hala.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup> Postpaid means a monthly plan, and Ooredoo&#39;s are Shahry+ and Qatarna+.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup> Check both operators&#39; sites for current prices, since plans and offers change.<sup class="footnote-ref"><a href="#fn6" id="fnref6:1">[6]</a></sup></p><h2 id="keep-your-number-tied-to-your-qid" tabindex="-1">Keep your number tied to your QID <a class="header-anchor" href="#keep-your-number-tied-to-your-qid" aria-label="Permalink to &quot;Keep your number tied to your QID&quot;">​</a></h2><p>Government apps such as Metrash use the mobile number linked to your QID, so take care when you change or share a line.<sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3]</a></sup> Ooredoo sends an SMS to the primary number on your QID when a new service is activated. You then have 7 days to tell Ooredoo if you did not ask for it.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></p><h2 id="home-internet" tabindex="-1">Home internet <a class="header-anchor" href="#home-internet" aria-label="Permalink to &quot;Home internet&quot;">​</a></h2><p>Vodafone and Ooredoo are both licensed for fixed services.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup> The details below are Vodafone&#39;s, so ask Ooredoo the same questions before you compare.</p><ul><li>Ask for an availability check first. Vodafone offers this through chat or a call back.<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup></li><li>Vodafone Home Fibre needs a building connected to its fibre. If yours is not connected, it offers Vodafone Home 5G plans.<sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup></li><li>You can sign up online, on WhatsApp, in a store or by phone.<sup class="footnote-ref"><a href="#fn8" id="fnref8:1">[8]</a></sup></li><li>Vodafone calls you to set the installation appointment. To change it later, use the My Vodafone app or call 111.<sup class="footnote-ref"><a href="#fn8" id="fnref8:2">[8]</a></sup></li><li>Read the lock-in. Vodafone requires at least three paid monthly bills, and charges QR 798 if you disconnect before twelve months.<sup class="footnote-ref"><a href="#fn8" id="fnref8:3">[8]</a></sup></li><li>If you move, one home move every 12 months is free. A second move in that period costs QR 200.<sup class="footnote-ref"><a href="#fn8" id="fnref8:4">[8]</a></sup></li></ul><h2 id="switching-operator" tabindex="-1">Switching operator <a class="header-anchor" href="#switching-operator" aria-label="Permalink to &quot;Switching operator&quot;">​</a></h2><p>You can move a mobile number or a fixed number to the other operator.<sup class="footnote-ref"><a href="#fn9" id="fnref9">[9]</a></sup> For a fixed number, pay all outstanding bills first. Ending a fixed service early can bring extra charges, so read your terms.<sup class="footnote-ref"><a href="#fn9" id="fnref9:1">[9]</a></sup></p><h2 id="making-a-complaint" tabindex="-1">Making a complaint <a class="header-anchor" href="#making-a-complaint" aria-label="Permalink to &quot;Making a complaint&quot;">​</a></h2><p>Go to your operator first. CRA says operators must resolve valid issues, and Ooredoo&#39;s terms ask you to give it the chance to fix the problem before you go elsewhere.<sup class="footnote-ref"><a href="#fn10" id="fnref10">[10]</a></sup><sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></p><ol><li>Complain through your operator&#39;s shop, contact centre or website, and keep the complaint reference number. CRA&#39;s form asks for it.<sup class="footnote-ref"><a href="#fn10" id="fnref10:1">[10]</a></sup></li><li>Dispute a bill quickly. Ooredoo&#39;s terms give you 45 days from the bill issue date.<sup class="footnote-ref"><a href="#fn2" id="fnref2:3">[2]</a></sup></li><li>Go to CRA if a mobile disconnection stays unresolved for 48 hours, a fixed disconnection for 72 hours, or any other complaint for 30 calendar days. You can also go at any time if the operator closes the complaint and you are not happy with the outcome.<sup class="footnote-ref"><a href="#fn11" id="fnref11">[11]</a></sup></li></ol><p>CRA&#39;s complaint channels are the <a href="https://www.cra.gov.qa/en/services/lodge-a-complaint" target="_blank" rel="noreferrer">online form</a>, the 24 hour hotline 103, the email <a href="mailto:consumervoice@cra.gov.qa" target="_blank" rel="noreferrer">consumervoice@cra.gov.qa</a>, the Arsel app, or a visit to its headquarters at Al Nasr Tower (B).<sup class="footnote-ref"><a href="#fn11" id="fnref11:1">[11]</a></sup></p><p>CRA investigates and may ask you for more details. It shares your identity and complaint with the operator only with your consent.<sup class="footnote-ref"><a href="#fn10" id="fnref10:2">[10]</a></sup></p><p>See also: <a href="./metrash">Metrash</a>, <a href="./housing-and-utilities">Housing and utilities</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Communications Regulatory Authority, <a href="https://www.cra.gov.qa/en/Services/Telecommunications/Licensing/Licensees" target="_blank" rel="noreferrer">Licensees</a>. Last checked: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn2" class="footnote-item"><p>Ooredoo Qatar, <a href="https://www.ooredoo.qa/web/en/general-terms-and-conditions-for-consumer-services/" target="_blank" rel="noreferrer">General terms and conditions</a>. Last checked: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:3" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn3" class="footnote-item"><p>Vodafone Qatar, <a href="https://www.vodafone.qa/en/help/faqs" target="_blank" rel="noreferrer">Help &amp; Frequently Asked Questions</a>. Last checked: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn4" class="footnote-item"><p>Vodafone Qatar, <a href="https://www.vodafone.qa/instant-sim" target="_blank" rel="noreferrer">Instant SIM</a>. Last checked: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn5" class="footnote-item"><p>Ooredoo Qatar, <a href="https://www.ooredoo.qa/web/en/prepaid-plans/" target="_blank" rel="noreferrer">Prepaid Plans</a>. Last checked: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn6" class="footnote-item"><p>Ooredoo Qatar, <a href="https://www.ooredoo.qa/web/en/postpaid-plans/" target="_blank" rel="noreferrer">Ooredoo Postpaid Plans</a>. Last checked: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref6:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn7" class="footnote-item"><p>Vodafone Qatar, <a href="https://www.vodafone.qa/en/services/home/gigahome" target="_blank" rel="noreferrer">Home Internet</a>. Last checked: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn8" class="footnote-item"><p>Vodafone Qatar, <a href="https://www.vodafone.qa/en/faqs/GigaHome" target="_blank" rel="noreferrer">Vodafone Home FAQs</a>. Last checked: 2026-10. <a href="#fnref8" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref8:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref8:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref8:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref8:4" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn9" class="footnote-item"><p>Communications Regulatory Authority, <a href="https://www.cra.gov.qa/en/press-releases/telecom-consumers-can-transfer-their-fixed-numbers-from-one-service-provider-to-another" target="_blank" rel="noreferrer">Telecom Consumers Can Transfer their Fixed Numbers from One Service Provider to Another</a>. Last checked: 2026-10. <a href="#fnref9" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref9:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn10" class="footnote-item"><p>Communications Regulatory Authority, <a href="https://www.cra.gov.qa/en/services/lodge-a-complaint" target="_blank" rel="noreferrer">Lodge a Complaint</a>. Last checked: 2026-10. <a href="#fnref10" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref10:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref10:2" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn11" class="footnote-item"><p>Communications Regulatory Authority, <a href="https://www.cra.gov.qa/en/press-releases/cra-launches-telecom-complaints-management-system" target="_blank" rel="noreferrer">CRA Launches Telecom Complaints Management System</a>. Last checked: 2026-10. <a href="#fnref11" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref11:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li></ol></section>',22)])])}const u=a(n,[["render",s]]);export{p as __pageData,u as default};
